function ActivityList({events=[]}) {return events.length?<div className="activity-list">{events.map((e,i)=><div className="activity-row" key={e.event_uuid||i}><span className="event-icon"><Activity size={15}/></span><div><strong>{humanize(e.action || e.status || 'Recorded event').replace(/_/g,' ')}</strong><p>{e.payload?.source_path || e.payload?.name || e.payload?.message || e.source_path || e.actor || 'Workspace'}</p><details><summary>Event details</summary><pre>{JSON.stringify(e.payload || e,null,2)}</pre></details></div><time>{time(e.occurred_at || e.at || e.started_at)}</time></div>)}</div>:<Empty title="No activity yet">Imports, review decisions, tags and exports appear here.</Empty>;}
// Read-only summaries may refresh after tags change without unmounting the
// active inspector. Mutation controls still use their fresh revision checks.
function useStableSummary(path,revision){
  const resource=useResource(path,revision),committed=useRef(path==='/projects'?{path,data:projectBootstrap()}:null);
  useEffect(()=>{if(resource.data&&!resource.error)committed.current={path,data:resource.data};},[path,resource.data,resource.error]);
  return {...resource,data:resource.data||(!resource.error&&committed.current?.path===path?committed.current.data:null)};
}
// Descriptor retention is presentation only. A changed project, actor or request
// owner cannot borrow it, and a refreshing descriptor pauses Inspector reads.
function useProtocolBrowse(id,projectId,structureRevision,active){
  const owner=useWorkspaceRequestScope(),profile=useAnnotationProfile();
  const scope=JSON.stringify([id,projectId,profile.profileUuid||'']);
  const revision=JSON.stringify([scope,structureRevision]);
  const resource=useResource(active?`/protocols/${id}?projection=browse`:null,revision);
  const committed=useRef(null);
  const invalid=resource.data&&(resource.data.definition?.protocol_uuid!==id||
    typeof resource.data.query_revision!=='string'||!resource.data.query_revision||
    !Number.isSafeInteger(resource.data.expected_binding_version)||resource.data.expected_binding_version<0||
    resource.data.definition?.project_uuid&&resource.data.definition.project_uuid!==projectId);
  const error=active?(resource.error||(invalid?'Protocol entry changed. Refresh before browsing.':null)):null;
  useEffect(()=>{if(active&&!resource.loading&&!error&&resource.data)committed.current={scope,owner,data:resource.data};},[active,resource.loading,error,resource.data,scope,owner]);
  const retained=committed.current?.scope===scope&&committed.current.owner===owner?committed.current.data:null;
  return {...resource,error,data:active&&!error?(resource.data||retained):null};
}
